INSERT INTO card_templates (id, name, name_si, element, rarity, lore) VALUES
  ('gaja-calf', 'Gaja Calf', 'ඇත් පැටියා', 'earth', 'common', 'Follows the Perahera drums and naps through the fire dancers.'),
  ('malu', 'Malu Sprite', 'මාළු', 'water', 'common', 'Lives in temple ponds and nibbles on lotus petals.'),
  ('monara', 'Monara Chick', 'මොනරා', 'wind', 'common', 'Practices its tail fan every morning, waiting for rain.'),
  ('ura', 'Ura Boarlet', 'වල් ඌරා', 'forest', 'uncommon', 'Roots through the forest floor looking for moonstones.'),
  ('simha', 'Simha Cub', 'සිංහ පැටියා', 'fire', 'uncommon', 'Its roar is still a squeak, but its mane is already ablaze.'),
  ('hansa', 'Hansa', 'හංස', 'water', 'uncommon', 'Glides across the lotus lake, leaving ripples of gold.'),
  ('gajasinghe', 'Gajasinghe', 'ගජසිංහ', 'earth', 'rare', 'Elephant strength, lion heart. Guards the old gateways.'),
  ('serapendiya', 'Serapendiya', 'සේරපෙන්දිය', 'wind', 'rare', 'Curled-beak bird of Sinhala art, carved on kasthane hilts.'),
  ('kinduru', 'Kinduru', 'කිඳුරු', 'forest', 'rare', 'Half bird, half maiden. Her harp song wakes the forest at dawn.'),
  ('naga-raksha', 'Naga Raksha', 'නාග රාක්ෂ', 'water', 'epic', 'Crowned with cobras, risen from the masks of Ambalangoda.'),
  ('gurulu-raksha', 'Gurulu Raksha', 'ගුරුළු රාක්ෂ', 'wind', 'epic', 'Strikes from the sky with a cobra in its beak.'),
  ('makara', 'Makara', 'මකර', 'water', 'legendary', 'Elephant front, lion feet, boar ear, fish body. Guardian of the thorana.')
